123	    if (!topic || !data) {
124	        FEATURE_LOG_ERROR("%s Invalid arguments", __FUNCTION__);
125	        return;
126	    }
127	    sensor_event_t* event = container_of(topic, sensor_event_t, topic);
128	    int cnt = datalen / sizeof(sensor_accel);
