276	static void unsubscribe(FeatureInstanceHandle feature, int magic, bool detach)
277	{
278	    FeatureProtoHandle proto_handle = FeatureGetProtoHandle(feature);
279	    SensorContext* th = static_cast<SensorContext*>(FeatureGetProtoData(proto_handle));
280	    sensor_event_t* event = th->events[magic];
281	    if (event == NULL || feature == nullptr) {
282	        return;
283	    }
284	
285	    // 1.active unsubsribe need invoke uv_topic_unsubscribe
286	    // 2.page jump,if not reserved need uv_topic_unsubscribe
287	    if (event->meta.subscribed) {
288	        int ret = uv_topic_unsubscribe(&event->topic);
289	        if (ret < 0) {
290	            if (detach) {
291	                event->meta.instance = nullptr;
292	            }
293	
294	            FEATURE_LOG_ERROR("%s::%s() call uv_topic_unsubscribe Failed,ret=%d", file_tag, __FUNCTION__, ret);
295	            goto exit;
296	        }
297	
298	        ret = uv_topic_close(&event->topic, NULL);
299	        if (ret < 0) {
300	            if (detach) {
301	                event->meta.instance = nullptr;
302	            }
303	
304	            FEATURE_LOG_ERROR("%s::%s()call uv_topic_close,ret = %d", file_tag, __FUNCTION__, ret);
305	            goto exit;
306	        }
307	
308	        event->meta.subscribed = false;
309	    }
310	
311	exit:
312	    FEATURE_LOG_INFO("%s unsubscribe success", __FUNCTION__);
313	    if (detach) {
314	        th->events[magic] = nullptr;
315	        return;
316	    }
317	
318	    if (FeatureCheckCallbackId(feature, event->meta.callback)) {
319	        FeatureRemoveCallback(feature, event->meta.callback);
320	    }
321	
322	    if (FeatureCheckCallbackId(feature, event->meta.fail)) {
323	        FeatureRemoveCallback(feature, event->meta.fail);
324	    }
325	}
