327	static bool subscribe(FeatureInstanceHandle feature, SensorContext* th, sensor_magic_e magic, MetaData* meta)
328	{
329	    int ret;
330	    int code;
331	    const char* msg = "";
332	    sensor_event_t* event = th->events[magic];
333	    FeatureManagerHandle manager = FeatureGetManagerHandleFromInstance(feature);
334	
335	    if (!FeatureCheckCallbackId(feature, meta->callback)) {
336	        code = ARGSERROR;
337	        msg = "callback id is invalid";
338	        goto errout;
339	    }
340	
341	    if (event && event->meta.subscribed) {
342	        REMOVE_ALL_CALLBACK(event->meta.callback, event->meta.fail);
343	        event->meta.fail = meta->fail;
344	        event->meta.callback = meta->callback;
345	        return true;
346	    }
347	
348	    event = static_cast<sensor_event_t*>(malloc(sizeof(sensor_event_t)));
349	    if (event == NULL) {
350	        code = GENERAL;
351	        msg = "malloc error";
352	        goto errout;
353	    }
354	
355	    event->meta = *meta;
356	    th->events[magic] = event;
357	    ret = uv_topic_subscribe(FeatureGetUVLoop(manager), &th->events[magic]->topic,
358	        sensor_orb_table[magic].meta,
359	        sensor_orb_table[magic].topic_cb);
360	    if (ret < 0) {
361	        code = GENERAL;
362	        msg = "subscribe error";
363	        th->events[magic] = NULL;
364	        free(event);
365	        FEATURE_LOG_ERROR("%s::%s() subscribe error:%d\n", file_tag, __FUNCTION__, ret);
366	        goto errout;
367	    }
368	    event->meta.subscribed = true;
369	    return true;
370	errout:
371	    INVOKE_FAIL_CB(feature, meta->fail, msg, code);
372	    REMOVE_ALL_CALLBACK(meta->callback, meta->fail);
373	    return false;
374	}
