376	void system_sensor_wrap_subscribeAccelerometer(FeatureInstanceHandle feature, AppendData data,
377	    system_sensor_Accelerometer* param)
378	{
379	    FeatureProtoHandle proto_handle = FeatureGetProtoHandle(feature);
380	    SensorContext* th = static_cast<SensorContext*>(FeatureGetProtoData(proto_handle));
381	    if (th == NULL) {
382	        FEATURE_LOG_ERROR("%s::%s() sensor context is NULL\n", file_tag, __FUNCTION__);
383	        return;
384	    }
385	
386	    int interval = 0;
387	    if (strcmp(param->interval, "game") == 0) {
388	        interval = 20000;
389	    } else if (strcmp(param->interval, "ui") == 0) {
390	        interval = 50000;
391	    } else if (strcmp(param->interval, "normal") == 0) {
392	        interval = 200000;
393	    } else {
394	        FEATURE_LOG_ERROR("%s::%s() param interval is invalid:%s\n", file_tag, __FUNCTION__,
395	            param->interval);
396	        return;
397	    }
398	
399	    MetaData meta;
400	    meta.instance = feature;
401	    meta.reserved = param->reserved;
402	    meta.callback = param->callback;
403	    meta.fail = param->fail;
404	
405	    if (subscribe(feature, th, SENSOR_MAGIC_ACCEL, &meta)) {
406	        int ret = uv_topic_set_interval(&th->events[SENSOR_MAGIC_ACCEL]->topic, interval);
407	        if (ret < 0) {
408	            FEATURE_LOG_ERROR("%s::%s() set interval error:%d\n", file_tag, __FUNCTION__, ret);
409	        }
410	    } else {
411	        FEATURE_LOG_ERROR("%s::%s() accel subscibe fail:%s\n", file_tag, __FUNCTION__);
412	    }
413	}
