630	static void sensor_topic_cb(uv_topic_t* topic, int status, void* data, size_t datalen)
631	{
632	    int ret;
633	    if (!topic || !data) {
634	        FEATURE_LOG_ERROR("%s Invalid arguments", __FUNCTION__);
635	        return;
636	    }
637	    sensor_event_t* event = container_of(topic, sensor_event_t, topic);
638	    sensorMulti_user_t* user = container_of(event, sensorMulti_user_t, event);
639	    ft_context_ref ft_ctx = user->ft_ctx;
640	    ft_value_t sensor_obj = ft_new_object(ft_ctx);
641	    ft_value_t ret_obj = ft_new_object(ft_ctx);
642	    sensor_magic_t magic = get_sensor_magic(user->type);
643	    switch (magic) {
644	    case SENSOR_MAGIC_GNSS: {
645	        sensor_gnss* ret_t = static_cast<sensor_gnss*>(data);
646	        ft_value_t latitude = ft_from_double(ft_ctx, round(ret_t->latitude * PRECISION) / PRECISION);
647	        ft_value_t longitude = ft_from_double(ft_ctx, round(ret_t->longitude * PRECISION) / PRECISION);
648	        ft_value_t altitude = ft_from_double(ft_ctx, round(ret_t->altitude * PRECISION) / PRECISION);
649	        ft_value_t speed = ft_from_double(ft_ctx, round(ret_t->ground_speed * PRECISION) / PRECISION);
650	        ft_value_t accuracy = ft_from_int(ft_ctx, static_cast<int>(ret_t->eph));
651	        ft_obj_set_property(ft_ctx, ret_obj, "latitude", latitude);
652	        ft_obj_set_property(ft_ctx, ret_obj, "longitude", longitude);
653	        ft_obj_set_property(ft_ctx, ret_obj, "altitude", altitude);
654	        ft_obj_set_property(ft_ctx, ret_obj, "speed", speed);
655	        ft_obj_set_property(ft_ctx, ret_obj, "accuracy", accuracy);
656	        ft_obj_set_property(ft_ctx, sensor_obj, "GPS", ret_obj);
657	        break;
658	    }
659	    case SENSOR_MAGIC_BARO: {
660	        sensor_baro* ret_t = static_cast<sensor_baro*>(data);
661	        ft_value_t pressure = ft_from_double(ft_ctx, round(ret_t->pressure * PRECISION) / PRECISION);
662	        ft_obj_set_property(ft_ctx, ret_obj, "pressure", pressure);
663	        ft_obj_set_property(ft_ctx, sensor_obj, "BAROMETER", ret_obj);
664	        break;
665	    }
666	    case SENSOR_MAGIC_ACCEL: {
667	        sensor_accel* ret_t = static_cast<sensor_accel*>(data);
668	        ft_value_t ret_x = ft_from_double(ft_ctx, round(ret_t->x * PRECISION) / PRECISION);
669	        ft_value_t ret_y = ft_from_double(ft_ctx, round(ret_t->y * PRECISION) / PRECISION);
670	        ft_value_t ret_z = ft_from_double(ft_ctx, round(ret_t->z * PRECISION) / PRECISION);
671	        ft_obj_set_property(ft_ctx, ret_obj, "x", ret_x);
672	        ft_obj_set_property(ft_ctx, ret_obj, "y", ret_y);
673	        ft_obj_set_property(ft_ctx, ret_obj, "z", ret_z);
674	        ft_obj_set_property(ft_ctx, sensor_obj, "ACCELEROMETER", ret_obj);
675	        break;
676	    }
677	    case SENSOR_MAGIC_PROX: {
678	        sensor_prox* ret_t = static_cast<sensor_prox*>(data);
679	        ft_value_t prox = ft_from_int(ft_ctx, ret_t->proximity);
680	        ft_obj_set_property(ft_ctx, ret_obj, "distance", prox);
681	        ft_obj_set_property(ft_ctx, sensor_obj, "PROXIMITY", ret_obj);
682	    }
683	    case SENSOR_MAGIC_LIGHT: {
684	        sensor_light* ret_t = static_cast<sensor_light*>(data);
685	        ft_value_t light = ft_from_int(ft_ctx, ret_t->light);
686	        ft_obj_set_property(ft_ctx, ret_obj, "light", light);
687	        ft_obj_set_property(ft_ctx, sensor_obj, "LIGHT", ret_obj);
688	        break;
689	    }
690	    case SENSOR_MAGIC_AMBIENTTEMPERATURE: {
691	        sensor_temp* ret_t = static_cast<sensor_temp*>(data);
692	        ft_value_t temp = ft_from_double(ft_ctx, round(ret_t->temperature * 10) / 10);
693	        ft_obj_set_property(ft_ctx, ret_obj, "temperature", temp);
694	        ft_obj_set_property(ft_ctx, sensor_obj, "AMBIENTTEMPERATURE", ret_obj);
695	        break;
696	    }
697	    case SENSOR_MAGIC_HUMIDITY: {
698	        sensor_humi* ret_t = static_cast<sensor_humi*>(data);
699	        ft_value_t humi = ft_from_int(ft_ctx, round(ret_t->humidity));
700	        ft_obj_set_property(ft_ctx, ret_obj, "humidity", humi);
701	        ft_obj_set_property(ft_ctx, sensor_obj, "HUMIDITY", ret_obj);
702	        break;
703	    }
704	    case SENSOR_MAGIC_COMPA: {
705	        sensor_compass* ret_t = static_cast<sensor_compass*>(data);
706	        double direction = (ret_t->direction * acos(-1.0)) / 180.0;
707	        if (direction > acos(-1.0)) {
708	            direction -= 2 * acos(-1.0);
709	        }
710	
711	        ft_value_t degree = ft_from_double(ft_ctx, direction);
712	        ft_value_t accuracy = ft_from_int(ft_ctx, ret_t->cal_status);
713	        ft_obj_set_property(ft_ctx, ret_obj, "direction", degree);
714	        ft_obj_set_property(ft_ctx, ret_obj, "accuracy", accuracy);
715	        ft_obj_set_property(ft_ctx, sensor_obj, "COMPASS", ret_obj);
716	        break;
717	    }
718	#ifdef CONFIG_MIWEAR_COMMON
719	    case SENSOR_MAGIC_WRIST_TILT: {
720	        algo_wrist_tilt* ret_t = static_cast<algo_wrist_tilt*>(data);
721	        if (ret_t->event != WRIST_TILT_UP) {
722	            ft_free_value(ft_ctx, sensor_obj);
723	            ft_free_value(ft_ctx, ret_obj);
724	            return;
725	        }
726	        break;
727	    }
728	#endif
729	    default:
730	        break;
731	    }
732	    ft_value_t* t_r_data = (ft_value_t*)FeatureMalloc(sizeof(ft_value_t), FT_ANY_REF);
733	    *t_r_data = sensor_obj;
734	    if (user->oneshot) {
735	        system_sensor_cb_param* t_r = system_sensorMalloccb_param();
736	        t_r->data = t_r_data;
737	        t_r->dataType = user->type;
738	        INVOKE_SUCCESS_CB(user->event.meta.instance, user->event.meta.callback, t_r);
739	        FeatureFreeValue(t_r);
740	    } else {
741	        INVOKE_SUCCESS_CB(user->event.meta.instance, user->event.meta.callback, t_r_data);
742	        FeatureFreeValue(t_r_data);
743	    }
744	
745	    ft_free_value(ft_ctx, sensor_obj);
746	    if (user->oneshot) {
747	        ret = uv_topic_unsubscribe(topic);
748	        if (ret < 0) {
749	            FEATURE_LOG_ERROR("%s::%s() uv_topic_unsubscribe fail", file_tag, __FUNCTION__);
750	        }
751	
752	        ret = uv_topic_close(topic, sensor_topic_close_cb);
753	        if (ret < 0) {
754	            FEATURE_LOG_ERROR("%s::%s() uv_topic_close fail", file_tag, __FUNCTION__);
755	        }
756	
757	        FeatureInstanceHandle feature = user->event.meta.instance;
758	        REMOVE_ALL_CALLBACK(user->event.meta.callback, user->event.meta.fail);
759	    }
760	}
