762	static void multi_unsubscribe(sensorMulti_event_t* multi_event, FtInt type, bool detach)
763	{
764	    int ret;
765	    auto target = multi_event->user_map.equal_range(type);
766	    for (auto it = target.first; it != target.second; ++it) {
767	        ret = uv_topic_unsubscribe(&it->second->event.topic);
768	        if (ret < 0) {
769	            FEATURE_LOG_ERROR("%s::%s() uv_topic_unsubscribe failed,ret=%d\n", file_tag, __FUNCTION__,
770	                ret);
771	        }
772	
773	        ret = uv_topic_close(&it->second->event.topic, sensor_topic_close_cb);
774	        if (ret < 0) {
775	            FEATURE_LOG_ERROR("%s::%s() uv_topic_close failed,ret=%d\n", file_tag, __FUNCTION__,
776	                ret);
777	        }
778	
779	        if (!detach) {
780	            FeatureInstanceHandle feature = it->second->event.meta.instance;
781	            REMOVE_ALL_CALLBACK(it->second->event.meta.callback, it->second->event.meta.fail);
782	        }
783	    }
784	
785	    if (!detach) {
786	        multi_event->user_map.erase(target.first, target.second);
787	    }
788	}
