806	FtInt system_sensor_wrap_subscribe(FeatureInstanceHandle feature, union AppendData append_data, system_sensor_subscribeParam* param)
807	{
808	    int fd = 0;
809	    int code = 0;
810	    const char* msg = "";
811	    int ret = 0;
812	    int interval = 0;
813	    sensor_magic_t magic;
814	    sensorMulti_user_t* user;
815	    sensorMulti_event_t* event;
816	    FeatureManagerHandle manager = FeatureGetManagerHandleFromInstance(feature);
817	    FeatureProtoHandle proto_handle = FeatureGetProtoHandle(feature);
818	    SensorContext* th = static_cast<SensorContext*>(FeatureGetProtoData(proto_handle));
819	    if (th == NULL) {
820	        FEATURE_LOG_ERROR("%s::%s() sensorMulti context is NULL\n", file_tag, __FUNCTION__);
821	        return -1;
822	    }
823	
824	    if (!FeatureCheckCallbackId(feature, param->callback)) {
825	        code = GENERAL;
826	        msg = "callback id is invalid";
827	        FEATURE_LOG_ERROR("%s::%s() callback id is invalid", file_tag, __FUNCTION__);
828	        goto errout;
829	    }
830	
831	    magic = get_sensor_magic(param->type);
832	    if (magic == SENSOR_MAGIC_NUM) {
833	        code = SERVICEUNAVAILABLE;
834	        msg = "current sensor is not support";
835	        FEATURE_LOG_ERROR("%s::%s() current sensor is not support", file_tag, __FUNCTION__);
836	        goto errout;
837	    }
838	
839	    event = th->multi_events[magic];
840	    if (!event) {
841	        event = new sensorMulti_event_t();
842	    }
843	    if (strcmp(param->interval, "low") == 0) {
844	        interval = LOW_INTERVAL;
845	    } else if (strcmp(param->interval, "mid") == 0) {
846	        interval = MID_INTERVAL;
847	    } else if (strcmp(param->interval, "high") == 0) {
848	        interval = HIGH_INTERVAL;
849	    } else {
850	        code = GENERAL;
851	        msg = "param interval is invalid";
852	        FEATURE_LOG_ERROR("%s::%s() param interval is invalid:%s\n", file_tag, __FUNCTION__,
853	            param->interval);
854	        goto errout;
855	    }
856	
857	    user = static_cast<sensorMulti_user_t*>(zalloc(sizeof(sensorMulti_user_t)));
858	    if (!user) {
859	        code = GENERAL;
860	        msg = "malloc user failed";
861	        FEATURE_LOG_ERROR("%s::%s() malloc user failed", file_tag, __FUNCTION__);
862	        goto errout;
863	    }
864	
865	    MetaData meta;
866	    meta.instance = feature;
867	    meta.reserved = param->reserved;
868	    meta.callback = param->callback;
869	    meta.fail = param->fail;
870	    user->ft_ctx = FeatureGetContext(feature);
871	    user->type = param->type;
872	    user->oneshot = false;
873	    user->event.meta = meta;
874	
875	    ret = uv_topic_subscribe(FeatureGetUVLoop(manager), &user->event.topic,
876	        sensor_orb_table[magic].meta,
877	        sensor_topic_cb);
878	    fd = user->event.topic.handle.io_watcher.fd;
879	    if (ret < 0) {
880	        code = GENERAL;
881	        msg = "uv_topic_subscribe error";
882	        FEATURE_LOG_ERROR("%s::%s() uv_topic_subscribe error:%d\n", file_tag, __FUNCTION__, ret);
883	        free(user);
884	        goto errout;
885	    }
886	
887	    ret = uv_topic_set_interval(&user->event.topic, interval);
888	    if (ret < 0) {
889	        code = GENERAL;
890	        msg = "set interval error";
891	        FEATURE_LOG_ERROR("%s::%s() set interval error:%d\n", file_tag, __FUNCTION__, ret);
892	        free(user);
893	        goto errout;
894	    }
895	
896	    event->user_map.insert(std::make_pair(fd, user));
897	    th->multi_events[magic] = event;
898	    return fd;
899	
900	errout:
901	    INVOKE_FAIL_CB(feature, param->fail, msg, code);
902	    REMOVE_ALL_CALLBACK(param->callback, param->fail);
903	    return -1;
904	}
