27	#define INVOKE_SUCCESS_CB(feature, cb, ...)                        \
28	    do {                                                           \
29	        if (!FeatureInvokeCallback(feature, cb, ##__VA_ARGS__)) {  \
30	            FEATURE_LOG_ERROR("invoke success callback failed !"); \
31	        }                                                          \
32	    } while (0)
33	
34	#define INVOKE_FAIL_CB(feature, cb, msg, code)                  \
35	    do {                                                        \
36	        if (!FeatureInvokeCallback(feature, cb, msg, code)) {   \
37	            FEATURE_LOG_ERROR("invoke fail callback failed !"); \
38	        }                                                       \
39	    } while (0)
40	
41	#define REMOVE_ALL_CALLBACK(feature, __succ__, __fail__) \
42	    do {                                                 \
43	        FeatureRemoveCallback(feature, __succ__);        \
44	        FeatureRemoveCallback(feature, __fail__);        \
45	    } while (0)
46	
47	#define HEALTH_INFO_INIT(magic_, index_, name_, meta_) \
48	    [magic_] = { .index = index_, .name = name_, .meta = meta_ }
49	
50	typedef enum HealthMagic {
51	    HEALTH_MAGIC_HEARTRATE,
52	    HEALTH_MAGIC_NUM,
53	} HealthMagic;
54	
55	struct HealthOrb {
56	    int index;
57	    const char* name;
58	    orb_id_t meta;
59	};
60	
61	struct HealthGetMeta {
62	    FtPromiseId pid = 0;
63	    int num;
64	    FtArray* array;
65	};
66	
67	struct HealthMetaData {
68	    FeatureInstanceHandle instance = 0;
69	    FtCallbackId callback = 0;
70	    FtCallbackId fail = 0;
71	    HealthGetMeta* getMeta = nullptr;
72	};
73	
74	struct HealthContext;
75	
76	struct HealthTopic {
77	    HealthContext* context;
78	    HealthMagic magic;
79	    std::list<uv_topic_t*> topic_list;
80	    std::list<HealthMetaData> getList;
81	    std::list<HealthMetaData> subList;
82	};
83	struct HealthContext {
84	    HealthTopic* event[HEALTH_MAGIC_NUM];
85	    ft_context_ref ft_ctx;
86	    int ref_count;
87	    bool isdestory;
88	};
