90	const static HealthOrb health_orb_table[HEALTH_MAGIC_NUM] = {
91	    HEALTH_INFO_INIT(HEALTH_MAGIC_HEARTRATE, 0, "HEART_RATE", ORB_ID(algo_heartrate)),
92	};
93	
94	static HealthMagic getHealthMagic(int type)
95	{
96	    for (int i = 0; i < HEALTH_MAGIC_NUM; i++) {
97	        if (health_orb_table[i].index == type) {
98	            return (HealthMagic)i;
99	        }
100	    }
101	
102	    return HEALTH_MAGIC_NUM;
103	}
