110	static std::list<HealthMetaData>::iterator health_find_meta(HealthTopic* event, FeatureInstanceHandle instance)
111	{
112	    for (auto it = event->subList.begin(); it != event->subList.end(); ++it) {
113	        if (it->instance == instance) {
114	            return it;
115	        }
116	    }
117	    return event->subList.end();
