120	static void health_topic_close_cb(uv_handle_t* handle)
121	{
122	    uv_topic_t* topic = (uv_topic_t*)handle;
123	    HealthTopic* event = static_cast<HealthTopic*>(topic->user_data);
124	    HealthContext* context = event->context;
125	    context->ref_count--;
126	    delete (topic);
127	    if (!context->ref_count && context->isdestory) {
128	        FEATURE_LOG_ERROR("%s::%s() delete context", file_tag, __FUNCTION__);
129	        delete context;
130	    }
131	}
132	
133	static void health_topic_cb(uv_topic_t* topic, int status, void* data, size_t datalen)
134	{
135	    int ret;
136	    HealthTopic* event = static_cast<HealthTopic*>(topic->user_data);
137	    cJSON* root = nullptr;
138	    cJSON* root_ = nullptr;
139	    char* json_str = nullptr;
140	    FtJsonObject rs = nullptr;
141	
142	    switch (event->magic) {
143	    case HEALTH_MAGIC_HEARTRATE: {
144	        size_t cnt = datalen / sizeof(algo_heartrate);
145	        for (size_t i = 0; i < cnt; i++) {
146	            struct algo_heartrate* hr_data = (struct algo_heartrate*)data + i;
147	
148	            root = cJSON_CreateObject();
149	            root_ = cJSON_CreateObject();
150	
151	            cJSON_AddNumberToObject(root_, "value", hr_data->bpm);
152	            cJSON_AddNumberToObject(root_, "timeStamp", hr_data->timestamp_us / 1000);
153	            cJSON_AddItemToObject(root, "data", root_);
154	            json_str = cJSON_Print(root);
155	            rs = FeatureNewJsonObject(json_str);
156	            for (auto it = event->subList.begin(); it != event->subList.end(); it++) {
157	                INVOKE_SUCCESS_CB(it->instance, it->callback, rs);
158	            }
159	
160	            if (i != cnt - 1 || event->getList.empty()) {
161	                FeatureFreeValue(rs);
162	                cJSON_Delete(root);
163	                rs = nullptr;
164	                json_str = nullptr;
165	                root = nullptr;
166	            }
167	
168	            free(json_str);
169	        }
170	
171	        break;
172	    }
173	    default:
174	        break;
175	    }
176	
177	    if (!event->getList.empty()) {
178	        HealthMetaData meta = event->getList.front();
179	        HealthGetMeta* getMeta = meta.getMeta;
180	
181	        cJSON_AddNumberToObject(root, "dataType", health_orb_table[event->magic].index);
182	        json_str = cJSON_Print(root);
183	        rs = FeatureNewJsonObject(json_str);
184	        FeatureArrayAppend(getMeta->array, rs);
185	        if (!--getMeta->num) {
186	            FeaturePromiseResolve(meta.instance, getMeta->pid, getMeta->array);
187	            FeatureFreeValue(getMeta->array);
188	            delete (getMeta);
189	        }
190	        event->getList.pop_front();
191	        FeatureFreeValue(rs);
192	        free(json_str);
193	        cJSON_Delete(root);
194	    }
195	
196	    if (!health_sensor_is_active(event) && !event->topic_list.empty()) {
197	        uv_topic_t* free_topic = event->topic_list.front();
198	        event->topic_list.pop_front();
199	        ret = uv_topic_unsubscribe(free_topic);
200	        if (ret < 0) {
201	            FEATURE_LOG_ERROR("%s::%s() uv_topic_unsubscribe fail", file_tag, __FUNCTION__);
202	        }
203	
204	        ret = uv_topic_close(free_topic, health_topic_close_cb);
205	        if (ret < 0) {
206	            FEATURE_LOG_ERROR("%s::%s() uv_topic_close fail", file_tag, __FUNCTION__);
207	        }
208	        return;
209	    }
210	}
