212	void service_health_wrap_getRecentSamples(FeatureInstanceHandle handle, AppendData append_data, FtPromiseId pid, service_health_getRecentSamplesParam* param)
213	{
214	    int ret;
215	    int code;
216	    const char* msg = "";
217	    HealthMagic magic;
218	    FeatureProtoHandle proto_handle = FeatureGetProtoHandle(handle);
219	    HealthContext* context = static_cast<HealthContext*>(FeatureGetProtoData(proto_handle));
220	    FeatureManagerHandle manager = FeatureGetManagerHandleFromInstance(handle);
221	    FtArray* types = param->dataTypes;
222	    int len = FeatureArrayGetLength(types);
223	    HealthGetMeta* getMeta;
224	    std::vector<std::pair<HealthTopic*, HealthMetaData>> tmpList;
225	
226	    if (!len) {
227	        FeaturePromiseReject(handle, pid, FT_ERR_ARGS, "dataTypes is empty");
228	        return;
229	    }
230	
231	    getMeta = new HealthGetMeta();
232	    if (!getMeta) {
233	        FeaturePromiseReject(handle, pid, FT_ERR_GENERAL, "malloc getMeta failed");
234	        return;
235	    }
236	
237	    getMeta->num = len;
238	    getMeta->pid = pid;
239	    for (int i = 0; i < len; i++) {
240	        HealthTopic* event;
241	        HealthMetaData meta;
242	        int type = *(int*)FeatureArrayGetData(types, i);
243	
244	        magic = getHealthMagic(type);
245	        if (magic == HEALTH_MAGIC_NUM) {
246	            getMeta->num--;
247	            continue;
248	        }
249	
250	        ret = orb_exists(health_orb_table[magic].meta, 0);
251	        if (ret < 0) {
252	            getMeta->num--;
253	            continue;
254	        }
255	
256	        event = context->event[magic];
257	        if (!event) {
258	            event = new HealthTopic();
259	            if (!event) {
260	                code = FT_ERR_GENERAL;
261	                msg = "malloc event failed";
262	                goto errout;
263	            }
264	
265	            event->context = context;
266	            event->magic = magic;
267	        }
268	
269	        if (!health_sensor_is_active(event)) {
270	            uv_topic_t* topic = new uv_topic_t();
271	            if (!topic) {
272	                code = FT_ERR_GENERAL;
273	                msg = "malloc topic failed";
274	                goto errout;
275	            }
276	
277	            ret = uv_topic_subscribe(FeatureGetUVLoop(manager), topic,
278	                health_orb_table[magic].meta,
279	                health_topic_cb);
280	            if (ret < 0) {
281	                delete (topic);
282	                code = FT_ERR_GENERAL;
283	                msg = "subscribe error";
284	                goto errout;
285	            }
286	
287	            topic->user_data = (void*)event;
288	            event->topic_list.push_back(topic);
289	            context->ref_count++;
290	        }
291	
292	        meta.instance = handle;
293	        meta.getMeta = getMeta;
294	        tmpList.emplace_back(event, meta);
295	    }
296	
297	    if (getMeta->num == 0) {
298	        code = FT_ERR_ARGS;
299	        msg = "no valid dataTypes to subscribe";
300	        goto errout;
301	    }
302	
303	    for (auto& p : tmpList) {
304	        p.first->getList.push_back(p.second);
305	    }
306	    getMeta->array = FeatureCreateArray(handle, getMeta->num, FT_JSON_OBJ);
307	
308	    return;
309	
310	errout:
311	    FeatureFreeValue(getMeta->array);
312	    delete (getMeta);
313	    FeaturePromiseReject(handle, pid, code, msg);
314	}
