316	void service_health_wrap_subscribeSample(FeatureInstanceHandle handle,
317	    AppendData adata,
318	    service_health_subscribeParam* param)
319	{
320	    int ret;
321	    int code;
322	    const char* msg = "";
323	    HealthMagic magic;
324	    HealthMetaData meta = {};
325	    FeatureManagerHandle manager = FeatureGetManagerHandleFromInstance(handle);
326	    FeatureProtoHandle proto_handle = FeatureGetProtoHandle(handle);
327	    HealthContext* context = static_cast<HealthContext*>(FeatureGetProtoData(proto_handle));
328	
329	    if (!FeatureCheckCallbackId(handle, param->callback)) {
330	        code = FT_ERR_ARGS;
331	        msg = "callback id is invalid";
332	        if (param->fail) {
333	            INVOKE_FAIL_CB(handle, param->fail, msg, code);
334	        }
335	        REMOVE_ALL_CALLBACK(handle, param->callback, param->fail);
336	        return;
337	    }
338	
339	    magic = getHealthMagic(param->dataType);
340	    if (magic == HEALTH_MAGIC_NUM) {
341	        code = FT_ERR_ARGS;
342	        msg = "data type is invalid";
343	        if (param->fail) {
344	            INVOKE_FAIL_CB(handle, param->fail, msg, code);
345	        }
346	        REMOVE_ALL_CALLBACK(handle, param->callback, param->fail);
347	        return;
348	    }
349	
350	    if (!context->event[magic]) {
351	        context->event[magic] = new HealthTopic();
352	        if (!context->event[magic]) {
353	            code = FT_ERR_GENERAL;
354	            msg = "malloc event failed";
355	            if (param->fail) {
356	                INVOKE_FAIL_CB(handle, param->fail, msg, code);
357	            }
358	            REMOVE_ALL_CALLBACK(handle, param->callback, param->fail);
359	            return;
360	        }
361	
362	        context->event[magic]->context = context;
363	        context->event[magic]->magic = magic;
364	    }
365	
366	    std::list<HealthMetaData>::iterator it = health_find_meta(context->event[magic], handle);
367	    if (it != context->event[magic]->subList.end()) {
368	        REMOVE_ALL_CALLBACK(handle, it->callback, it->fail);
369	        it->callback = param->callback;
370	        it->fail = param->fail;
371	        return;
372	    }
373	
374	    if (!health_sensor_is_active(context->event[magic])) {
375	        uv_topic_t* topic = new uv_topic_t();
376	        if (!topic) {
377	            code = FT_ERR_GENERAL;
378	            msg = "malloc topic failed";
379	            if (param->fail) {
380	                INVOKE_FAIL_CB(handle, param->fail, msg, code);
381	            }
382	            REMOVE_ALL_CALLBACK(handle, param->callback, param->fail);
383	            return;
384	        }
385	
386	        ret = uv_topic_subscribe(FeatureGetUVLoop(manager),
387	            topic,
388	            health_orb_table[magic].meta,
389	            health_topic_cb);
390	        if (ret < 0) {
391	            delete topic;
392	            code = FT_ERR_GENERAL;
393	            msg = "subscribe error";
394	            if (param->fail) {
395	                INVOKE_FAIL_CB(handle, param->fail, msg, code);
396	            }
397	            REMOVE_ALL_CALLBACK(handle, param->callback, param->fail);
398	            return;
399	        }
400	
401	        topic->user_data = (void*)context->event[magic];
402	        context->event[magic]->topic_list.push_back(topic);
403	        context->ref_count++;
404	    }
405	
406	    meta.instance = handle;
407	    meta.callback = param->callback;
408	    meta.fail = param->fail;
409	    context->event[magic]->subList.push_back(meta);
410	}
411	
412	static void unsubscribe(HealthTopic* event, FeatureInstanceHandle handle)
413	{
414	    int ret;
415	    auto it = health_find_meta(event, handle);
416	    if (it == event->subList.end()) {
417	        return;
418	    }
419	
420	    REMOVE_ALL_CALLBACK(handle, it->callback, it->fail);
421	    event->subList.erase(it);
422	    if (!health_sensor_is_active(event) && !event->topic_list.empty()) {
423	        uv_topic_t* free_topic = event->topic_list.front();
424	        event->topic_list.pop_front();
425	        ret = uv_topic_unsubscribe(free_topic);
426	        if (ret < 0) {
427	            FEATURE_LOG_ERROR("%s topic unsubscribe failed", __FUNCTION__);
428	        }
429	
430	        ret = uv_topic_close(free_topic, health_topic_close_cb);
431	        if (ret < 0) {
432	            FEATURE_LOG_ERROR("%s::%s() uv_topic_close fail", file_tag, __FUNCTION__);
433	        }
434	    }
435	}
