  type: DATA_TYPES.ACCELEROMETER,
  success: function(data) { },
  fail: function(data, code) { },
  complete: function() { }
})

// 检查传感器是否可用
sensor.checkAvailable(DATA_TYPES.ACCELEROMETER)  // 返回 boolean
