### 6. 姿态识别应用示例

基于以上 API，姿态识别的核心实现：

```javascript
import sensor from '@system.sensor'
import vibrator from '@system.vibrator'

export default {
  private: {
    isMonitoring: false,
    currentPosture: 'unknown',
    lastAngle: 0
  },

  // 开始监测
  startMonitor() {
    this.isMonitoring = true
    sensor.subscribeAccelerometer({
      interval: 'ui',  // 50ms 采样
      callback: (data) => {
        this.processSensorData(data)
      }
    })
  },

  // 处理传感器数据
  processSensorData(data) {
    // 计算倾斜角度 (俯仰角)
    const pitch = Math.atan2(
      data.y,
      Math.sqrt(data.x * data.x + data.z * data.z)
    ) * 180 / Math.PI

    // 姿态判断
    let posture = 'good'
    if (Math.abs(pitch) > 30) {
      posture = 'poor'
      this.triggerAlert()
    } else if (Math.abs(pitch) > 15) {
      posture = 'fair'
    }

    this.currentPosture = posture
    this.lastAngle = pitch
  },

  // 触发振动提醒
  triggerAlert() {
    vibrator.vibrate()
  },

  // 停止监测
  stopMonitor() {
    this.isMonitoring = false
    sensor.unsubscribeAccelerometer()
  }
}
```

